command/lifecycle/versiondrift command/lifecycle/version_drift.go
command/lifecycle/versiondrift command/lifecycle/control_plane_version_drift.go
command/lifecycle/versiondrift command/lifecycle/control_plane_version_drift_test.go
command/lifecycle/resize command/lifecycle/runtime_resize.go
command/lifecycle/pin command/lifecycle/pin*.go
command/lifecycle/pin command/lifecycle/job_worktree_test.go
command/lifecycle/pin command/lifecycle/work_clone_reclaim_test.go
command/lifecycle/pin command/lifecycle/repo_root_test.go
command/lifecycle/upgrade command/lifecycle/upgrade*.go
command/lifecycle/stop command/lifecycle/stop*.go
command/lifecycle/stop command/lifecycle/deploy_kubernetes_check_test.go
command/lifecycle/stop command/lifecycle/registry_credential_secret_test.go
command/lifecycle/envdelete command/lifecycle/delete*.go
